const links=[[[35.7,139.7],[37.6,-122.4]],[[35.7,139.7],[51.5,-.1]],[[35.7,139.7],[1.3,103.8]],[[35.7,139.7],[-33.9,151.2]],[[51.5,-.1],[40.7,-74]],[[1.3,103.8],[19.1,72.9]],[[37.6,-122.4],[40.7,-74]]].map(([a,b],i)=>({startLat:a[0],startLng:a[1],endLat:b[0],endLng:b[1],color:i%2?'#148cce':'#26e7ff'}));
